import ipaddress

def is_local(host):
    if host == "localhost":
        return True
    try:
        return ipaddress.ip_address(host).is_loopback
    except ValueError:
        return False

OPEN = {22, 8080}
fake_connect = lambda host, port: port in OPEN

def scan(host, ports, connect):
    if not is_local(host):
        raise PermissionError("authorized hosts only")
    return sorted(p for p in ports if connect(host, p))

print(scan("127.0.0.1", [21, 22, 80, 8080], fake_connect))
try:
    scan("8.8.8.8", [80], fake_connect)
except PermissionError as e:
    print(e)

